import{_ as n,o as a,c as t,a2 as o}from"./chunks/framework.BZO4qERu.js";const p=JSON.parse('{"title":"LINE","description":"","frontmatter":{},"headers":[],"relativePath":"zh/integrations/channels/line.md","filePath":"zh/integrations/channels/line.md","lastUpdated":1785920317000}'),s={name:"zh/integrations/channels/line.md"};function l(r,e,i,g,h,c){return a(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="line" tabindex="-1">LINE <a class="header-anchor" href="#line" aria-label="Permalink to &quot;LINE&quot;">​</a></h1><p>接上 LINE 后，用户加机器人绑定的 LINE 官方账号为好友，即可 1 对 1 聊天。</p><h2 id="先决条件-公网-https" tabindex="-1">先决条件：公网 HTTPS <a class="header-anchor" href="#先决条件-公网-https" aria-label="Permalink to &quot;先决条件：公网 HTTPS&quot;">​</a></h2><p>LINE 用 <strong>webhook</strong> 推消息进来，出站图片也是 LINE 服务器来你这边抓，所以部署必须有公网 HTTPS 入口，二选一：</p><ul><li>设 <code>MEMOH_WEBHOOK_PUBLIC_BASE_URL</code> 为公网 HTTPS origin（不能带路径、端口、内网地址）；</li><li>或在 server deploy 里启用 Cloudflare Quick Tunnel profile，Memoh 会自动拿到公网地址。</li></ul><h2 id="_1-建-messaging-api-channel" tabindex="-1">1. 建 Messaging API channel <a class="header-anchor" href="#_1-建-messaging-api-channel" aria-label="Permalink to &quot;1. 建 Messaging API channel&quot;">​</a></h2><ol><li>打开 <a href="https://developers.line.biz/console/" target="_blank" rel="noreferrer">LINE Developers Console</a>。</li><li>建（或选）一个 provider，在下面创建 <strong>Messaging API</strong> channel，它会关联一个 LINE 官方账号。</li><li><strong>Basic settings</strong> 里复制 <strong>Channel secret</strong>。</li><li><strong>Messaging API</strong> tab 里签发并复制 <strong>Channel access token</strong>（长效）。</li></ol><blockquote><p>官方文档：<a href="https://developers.line.biz/en/docs/messaging-api/getting-started/" target="_blank" rel="noreferrer">Messaging API - Getting Started</a></p></blockquote><h2 id="_2-在-memoh-里填" tabindex="-1">2. 在 Memoh 里填 <a class="header-anchor" href="#_2-在-memoh-里填" aria-label="Permalink to &quot;2. 在 Memoh 里填&quot;">​</a></h2><ol><li>机器人 <strong>Platforms</strong> → <strong>Add Channel</strong> → <strong>LINE</strong>。</li><li>贴 <strong>Channel Secret</strong> 和 <strong>Channel Access Token</strong>。</li><li><strong>Save</strong>（或 <strong>Save and Enable</strong>）。回调 URL 要保存之后才会生成。</li></ol><h2 id="_3-注册-webhook" tabindex="-1">3. 注册 webhook <a class="header-anchor" href="#_3-注册-webhook" aria-label="Permalink to &quot;3. 注册 webhook&quot;">​</a></h2><p>保存后面板会显示只读的 <strong>WebHook Callback URL</strong>，格式：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://&lt;公网 base&gt;/channels/line/webhook/&lt;config_id&gt;</span></span></code></pre></div><p>两种注册方式：</p><ul><li>点 <strong>Set in LINE</strong>——Memoh 直接通过 Messaging API 把地址写进你的 LINE channel。有未保存的改动会先报错，保存了再点。</li><li>或点 <strong>Copy</strong>，去 LINE Developers Console 的 <strong>Messaging API → Webhook URL</strong> 手动粘贴。</li></ul><p>最后确认 LINE 控制台里 <strong>Use webhook</strong> 是打开的。面板若提示拿不到公网 base URL，先回去解决第一步的公网 HTTPS。</p><h2 id="支持的能力" tabindex="-1">支持的能力 <a class="header-anchor" href="#支持的能力" aria-label="Permalink to &quot;支持的能力&quot;">​</a></h2><ul><li><strong>1 对 1 私聊</strong>：用户加官方账号好友即可开聊。</li><li><strong>入站</strong>：文本、图片、文件（图片需是 LINE 自己托管的，App 里直接发照片就是这种）。</li><li><strong>出站</strong>：文本 + PNG/JPEG 图片。</li><li>webhook 带签名校验（用 Channel Secret 验），事件 24 小时内去重。</li></ul><h2 id="限制" tabindex="-1">限制 <a class="header-anchor" href="#限制" aria-label="Permalink to &quot;限制&quot;">​</a></h2><ul><li><strong>只支持私聊</strong>。群和多人聊天室的消息会被忽略，把机器人拉进 LINE 群没有用。</li><li>入站的<strong>语音、视频、贴图、位置</strong>不处理。</li><li>出站图片必须公网 HTTPS 可访问，且符合 LINE 体积限制（原图 10 MB、预览图 1 MB）；图片之外的附件发不出去。</li><li>回复走 LINE <strong>Push API</strong>，计入你 LINE 套餐的推送条数配额。</li><li>不支持流式输出，回复整条整条到。</li><li>超长回复按 LINE 的 5000 字符上限拆成多条。</li></ul>',20)])])}const b=n(s,[["render",l]]);export{p as __pageData,b as default};
